//! "Calibrate before printing": measure the plate (bed levelling) at the start of the job.
//!
//! The Ender-3 V3 KE runs Klipper (Creality OS), and printers reached through Moonraker do
//! too. Klipper's documented command for this is BED_MESH_CALIBRATE. It is added to the
//! print file after the plate has reached temperature (a hot plate is the shape it prints
//! on), followed by homing again, so it works the same over either connection.

/// Lines added to the print file when calibration is on.
pub const CALIBRATION_GCODE: &str =
    "G28 ; home again now the plate is hot\nBED_MESH_CALIBRATE ; printer calibration: measure the plate\n";

/// The print file with the calibration step added (once) after the plate-heat wait, or
/// after the first home move, or at the very start when neither is found.
pub fn with_calibration(gcode: &str) -> String {
    if gcode.contains("BED_MESH_CALIBRATE") {
        return gcode.to_string();
    }
    let after = |prefix: &str| {
        let mut offset = 0;
        for line in gcode.split_inclusive('\n') {
            offset += line.len();
            if line.trim_start().starts_with(prefix) {
                return Some(offset);
            }
        }
        None
    };
    let at = after("M190").or_else(|| after("G28")).unwrap_or(0);
    let mut out = String::with_capacity(gcode.len() + CALIBRATION_GCODE.len() + 1);
    out.push_str(&gcode[..at]);
    if at > 0 && !out.ends_with('\n') {
        out.push('\n');
    }
    out.push_str(CALIBRATION_GCODE);
    out.push_str(&gcode[at..]);
    out
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn calibrates_after_plate_is_hot() {
        let g = "M140 S60\nG28 ; home\nM190 S60 ; wait for bed\nM109 S210\nG1 X1\n";
        let out = with_calibration(g);
        let bed = out.find("M190").unwrap();
        let cal = out.find("BED_MESH_CALIBRATE").unwrap();
        let nozzle = out.find("M109").unwrap();
        assert!(bed < cal && cal < nozzle, "{out}");
        assert_eq!(out.matches("BED_MESH_CALIBRATE").count(), 1);
    }

    #[test]
    fn added_only_once() {
        let once = with_calibration("G28\nG1 X1\n");
        assert_eq!(with_calibration(&once), once);
    }

    #[test]
    fn falls_back_to_start_of_file() {
        assert!(with_calibration("G1 X1\n").starts_with("G28"));
    }

    #[test]
    fn our_own_print_file_gets_it_after_the_plate_heat_wait() {
