    // A zone the person chose on purpose is respected.
    std::env::set_var("TZ", "Europe/London");
    use_system_time_zone();
    assert_eq!(std::env::var("TZ").as_deref(), Ok("Europe/London"));
    std::env::remove_var("TZ");
}

